labs.solution:
async function filterAsync(list, check) {
  const flags = await Promise.all(list.map(check));
  return list.filter((_, i) => flags[i]);
}

async function inBatches(tasks, size) {
  const out = [];
  for (let i = 0; i < tasks.length; i += size) {
    const batch = tasks.slice(i, i + size).map((t) => t());
    out.push(...(await Promise.all(batch)));
  }
  return out;
}

