labs.solution:
function onClick(event) {
  const item = event.target.closest("[data-id]");
  return item ? item.dataset.id : null;
}

function route(event, handlers) {
  const button = event.target.closest("[data-action]");
  if (!button) return undefined;
  return handlers[button.dataset.action]?.();
}

function listenOnce(target, type, handler) {
  target.addEventListener(type, handler, { once: true });
}

function subscribe(target, handler) {
  target.addEventListener("ping", handler);
  return () => target.removeEventListener("ping", handler);
}

function debounce(f, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => f(...args), ms);
  };
}

function throttle(f, ms) {
  let blocked = false;
  return (...args) => {
    if (blocked) return;
    blocked = true;
    f(...args);
    setTimeout(() => { blocked = false; }, ms);
  };
}

